let lang='zh', report=null, parsed=null, selectedId=null, filter='all', decisions={}, isSample=true, dirty=false, runSnapshot='', sourceName='synthetic-interview.srt', sampleSnapshot='';
let rangeValues=[{start:'8',end:'16'}];
const t=key=>msg[lang][key]??key;
let zhRules={};
const localRule=(issue,key)=>lang==='zh'&&zhRules[issue.ruleId]?.[key] ? zhRules[issue.ruleId][key] : issue[key];
const time=s=>formatTimestamp(Number(s)||0).replace(/^00:/,'');
function notice(text,type=''){const n=$('#notice');n.hidden=!text;n.textContent=text;n.className='notice '+type;}
function byteLength(s){return new TextEncoder().encode(s).length;}
function parseTime(v){const x=String(v).trim();if(/^\d+(?:\.\d+)?$/.test(x))return Number(x);const m=x.match(/^(?:(\d+):)?(\d{1,2}):(\d{2})(?:\.(\d{1,3}))?$/);if(!m||Number(m[2])>=60||Number(m[3])>=60)return NaN;return Number(m[1]||0)*3600+Number(m[2])*60+Number(m[3])+Number((m[4]||'').padEnd(3,'0'))/1000;}
function currentInputs(){return {source:$('#source').value,format:$('#format').value,ranges:rangeValues.map(r=>({start:parseTime(r.start),end:parseTime(r.end)})),title:$('#draft-title').value,copy:$('#draft-copy').value,contextWindowSeconds:12};}
function snapshot(){return JSON.stringify(currentInputs());}
function setDirty(){dirty=snapshot()!==runSnapshot;$('.workspace').classList.toggle('stale',dirty);$('.review-panel').inert=dirty;$('#input-state').textContent=t(dirty?'inputChanged':'inputReady');for(const id of ['export-md','export-json'])$('#'+id).disabled=dirty||!report;}
function renderRanges(){const container=$('#ranges');container.innerHTML=rangeValues.map((r,i)=>`<div class="range-row"><span class="range-number">${String(i+1).padStart(2,'0')}</span><input type="text" inputmode="decimal" maxlength="30" value="${escape(r.start)}" aria-label="${t('start')} ${i+1}" data-range="${i}" data-edge="start"><span class="arrow">→</span><input type="text" inputmode="decimal" maxlength="30" value="${escape(r.end)}" aria-label="${t('end')} ${i+1}" data-range="${i}" data-edge="end"><button aria-label="${t('removeRange')} ${i+1}" data-remove="${i}" ${rangeValues.length===1?'disabled':''}>×</button></div>`).join('');container.querySelectorAll('input').forEach(el=>el.addEventListener('input',()=>{rangeValues[Number(el.dataset.range)][el.dataset.edge]=el.value;setDirty();}));container.querySelectorAll('[data-remove]').forEach(el=>el.addEventListener('click',()=>{rangeValues.splice(Number(el.dataset.remove),1);renderRanges();setDirty();$('#add-range').focus();}));}
function updateSampleTag(){$('#sample-tag').textContent=t(isSample?'synthetic':'sourceImported');}
function applyLanguage(){document.documentElement.lang=lang==='zh'?'zh-CN':'en';document.title=lang==='zh'?'ClipLint · 剪辑审校台':'ClipLint · Source review workbench';document.querySelectorAll('[data-i18n]').forEach(el=>el.textContent=t(el.dataset.i18n));$('#language').textContent=lang==='zh'?'EN':'中文';$('#language').setAttribute('aria-label',lang==='zh'?'Switch language to English':'切换到中文');renderRanges();updateSampleTag();setDirty();render();}
function loadSample(){const s=samples[lang];$('#source').value=s.source;$('#format').value=s.format;$('#draft-title').value=s.title;$('#draft-copy').value=s.copy;rangeValues=s.ranges.map(r=>({start:String(r.start),end:String(r.end)}));isSample=true;sourceName=`synthetic-${lang}.srt`;decisions={};renderRanges();updateSampleTag();runReview(false);sampleSnapshot=snapshot();}
function runReview(showNotice=true,preserved=null){try{const input=currentInputs();if(byteLength(input.source)>MAX_BYTES)throw Error(t('sourceLarge'));if(input.title.length>500||input.copy.length>10000)throw Error(t('inputLimit'));if(!input.ranges.length||input.ranges.length>MAX_RANGES||input.ranges.some(r=>!Number.isFinite(r.start)||!Number.isFinite(r.end)||r.start<0||r.end<=r.start))throw Error(t('rangeInvalid'));const nextParsed=parseTranscript(input.source,{format:input.format});const expandedChars=input.ranges.reduce((n,r)=>n+nextParsed.cues.filter(c=>c.end>r.start&&c.start<r.end).reduce((m,c)=>m+c.text.length+1,0),0);if(expandedChars>4_000_000)throw Error(lang==='zh'?'重复范围产生的选中稿件超过 400 万字符，请减少重复段或拆分项目。':'Expanded selection exceeds 4 million characters. Reduce repeated ranges or split the project.');const nextReport=reviewClip({transcript:nextParsed,ranges:input.ranges,title:input.title,copy:input.copy,contextWindowSeconds:12});const changed=runSnapshot&&snapshot()!==runSnapshot;parsed=nextParsed;report=nextReport;decisions=preserved??(changed?{}:decisions);const ids=new Set(report.issues.map(i=>i.id));decisions=Object.fromEntries(Object.entries(decisions).filter(([id,d])=>ids.has(id)&&['reviewed','dismissed'].includes(d.status)&&typeof d.reason==='string'&&d.reason.trim().length>=3&&d.signature===issueSignature(report.issues.find(i=>i.id===id))));selectedId=report.issues[0]?.id??null;filter='all';runSnapshot=snapshot();setDirty();render();if(showNotice)notice(changed?t('clearDecisions'):'');else notice('');if(report.warnings?.length&&showNotice)notice(`${t('warning')}: ${report.warnings.map(w=>w.message).join(' ')}`);}catch(e){report=null;parsed=null;selectedId=null;decisions={};dirty=true;$('.workspace').classList.remove('stale');$('#input-state').textContent=t('parseError');$('#export-md').disabled=true;$('#export-json').disabled=true;render();notice(t('invalid')+(e.message||String(e)),'error');}}
function status(issue){return decisions[issue.id]?.status||'open';}
function render(){renderSummary();renderFindings();renderDetail();renderCoverage();}
function renderSummary(){const issues=report?.issues||[],done=issues.filter(i=>status(i)!=='open').length;$('#issue-count').textContent=issues.length;$('#summary-label').textContent=t(!report?'parseError':issues.length?'needReview':'noSignals');$('#summary-subtitle').textContent=report?t('subtitle'):t('parseError');$('#progress-label').textContent=`${done} / ${issues.length} ${t('progress')}`;$('#progress-fill').style.width=`${issues.length?done/issues.length*100:0}%`;$('#filter-tabs').innerHTML=['all','open','reviewed','dismissed'].map(s=>`<button class="filter-button" data-filter="${s}" aria-pressed="${filter===s}">${t(s)}<span>${s==='all'?issues.length:issues.filter(i=>status(i)===s).length}</span></button>`).join('');$('#filter-tabs').querySelectorAll('button').forEach(b=>b.addEventListener('click',()=>{filter=b.dataset.filter;const visible=issues.filter(i=>filter==='all'||status(i)===filter);if(!visible.some(i=>i.id===selectedId))selectedId=visible[0]?.id||null;render();$(`[data-filter="${filter}"]`)?.focus();}));}
function renderFindings(){const all=report?.issues||[];const issues=all.filter(i=>filter==='all'||status(i)===filter);const el=$('#findings-list');if(!issues.length){el.innerHTML=`<div class="empty"><span class="empty-mark">${report?'[ ]':'—'}</span><h3>${t(!report?'parseError':all.length?'emptyFilter':'emptySafe')}</h3><p>${t(all.length?'emptyFilterDesc':'emptySafeDesc')}</p></div>`;return;}el.innerHTML=issues.map(i=>`<button class="finding" data-issue="${escape(i.id)}" aria-pressed="${i.id===selectedId}"><div class="finding-meta"><span class="severity ${escape(i.severity)}">${t(i.severity)}</span><span class="rule-code">${escape(i.ruleId)}</span></div><h3>${escape(localRule(i,'title'))}</h3><p>${escape((localRule(i,'message')||'').slice(0,110))}${(localRule(i,'message')||'').length>110?'…':''}</p><div class="finding-bottom"><span class="finding-time">${i.evidence?.length?time(i.evidence[0].start)+' → '+time(i.evidence[0].end):'DRAFT'}</span><span class="finding-status">${t(status(i))} ${i.id===selectedId?'↗':''}</span></div></button>`).join('');el.querySelectorAll('button').forEach(b=>b.addEventListener('click',()=>{selectedId=b.dataset.issue;renderFindings();renderDetail();$(`[data-issue="${selectedId}"]`)?.focus();}));}
function getContext(issue){if(!parsed?.cues?.length)return[];const ids=new Set((issue.evidence||[]).map(e=>e.cueId));const indices=parsed.cues.flatMap((c,i)=>ids.has(c.id)?[i]:[]);if(!indices.length){const i=parsed.cues.findIndex(c=>isKept(c));if(i>=0)indices.push(i);}const chosen=new Set(indices);for(const i of indices)for(const n of [i-1,i+1])if(n>=0&&n<parsed.cues.length&&chosen.size<12)chosen.add(n);return [...chosen].sort((a,b)=>a-b).map(i=>parsed.cues[i]);}
function isKept(cue){return(report?.selection?.ranges||[]).some(r=>cue.end>r.start&&cue.start<r.end);}
function cueLabel(cue){if(!isKept(cue))return 'omitted';return report.selection.ranges.some(r=>cue.start>=r.start-.001&&cue.end<=r.end+.001)?'kept':'partial';}
function issueSignature(i){return JSON.stringify([report.engine.version,i.ruleId,i.assessment,i.message,i.uncertainty,i.rangeIndex,i.draftField,i.draftSpan,i.evidence]);}
function cueBody(c){const speaker=c.speaker?`<span class="cue-speaker">${escape(c.speaker)}</span>`:'';const short=escape(c.text.slice(0,1800));return speaker+(c.text.length>1800?`<details class="full-cue"><summary>${short}… <b>${lang==='zh'?'展开完整字幕':'Expand full cue'}</b></summary><p>${escape(c.text)}</p></details>`:short);}
function renderDetail(){const el=$('#evidence-panel');const issue=report?.issues.find(i=>i.id===selectedId);if(!issue){el.innerHTML=`<div class="empty"><span class="empty-mark">[ : ]</span><h3>${t('unassessed')}</h3><p>${t('emptySafeDesc')}</p></div>`;return;}const context=getContext(issue);const evIds=new Set((issue.evidence||[]).map(e=>e.cueId));const decision=decisions[issue.id];const draftField=issue.draftField==='title'?'title':issue.draftField==='copy'?'copy':null;let draft=draftField?report.draft[draftField]:report.draft.title;const evidenceHtml=context.length?context.map(c=>`<div class="context-row ${isKept(c)?'selected':''} ${evIds.has(c.id)?'evidence':''}"><div class="context-time">${time(c.start)}<span class="context-tag">${t(cueLabel(c))}</span></div><div class="context-text">${cueBody(c)}</div></div>`).join(''):`<div class="context-row">${t('noContext')}</div>`;el.innerHTML=`<div class="detail-kicker"><span>${t(issue.assessment==='deterministic'?'deterministic':'heuristic')}</span><span>${String(report.issues.indexOf(issue)+1).padStart(2,'0')} / ${String(report.issues.length).padStart(2,'0')}</span></div><h3>${escape(localRule(issue,'title'))}</h3><p class="detail-desc">${escape(localRule(issue,'message'))}${lang==='zh'&&zhRules[issue.ruleId]?.message?`<br><span lang="en">${escape(issue.message)}</span>`:''}</p>${draft?`<div class="evidence-label"><span>${t('draft')}</span><span>${t(draftField==='copy'?'copyLabel':'titleLabel')}</span></div><div class="draft-excerpt">${escape(draft)}</div>`:''}<div class="evidence-label"><span>${t('context')}</span><span>${t('selectedLabel')}</span></div><div class="transcript-context">${evidenceHtml}</div><div class="timeline" aria-hidden="true">${(parsed?.cues||[]).filter((c,i,a)=>i%Math.max(1,Math.ceil(a.length/150))===0).map(c=>`<span class="cue-bar ${isKept(c)?'keep':''}" style="flex:${Math.max(.01,c.end-c.start)}"></span>`).join('')}</div><div class="timeline-label"><span>00:00.000</span><span>${time(report.source.duration)}</span></div>${issue.suggestion?`<p class="detail-desc" style="margin-top:14px">${escape(localRule(issue,'suggestion'))}</p>`:''}${issue.uncertainty?`<details class="uncertainty"><summary>${lang==='zh'?'为什么这不是结论':'Why this is not a verdict'}</summary><p lang="en">${escape(issue.uncertainty)}</p></details>`:''}<div class="decision-area"><label for="review-reason">${t('reviewReason')}</label><textarea id="review-reason" rows="2" maxlength="2000" placeholder="${escape(t('reasonPlaceholder'))}">${escape(decision?.reason||'')}</textarea><div class="decision-actions"><button class="review-button" data-decision="reviewed">${t('markReviewed')}</button><button class="dismiss-button" data-decision="dismissed">${t('dismiss')}</button>${decision?`<button class="text-button" id="reopen">${t('reopen')}</button>`:''}</div>${decision?`<p class="decision-status">${t('reviewSaved')} ${t(decision.status)} · ${escape(new Date(decision.at).toLocaleString(lang==='zh'?'zh-CN':'en-GB'))}</p>`:''}</div>`;el.querySelectorAll('[data-decision]').forEach(b=>b.addEventListener('click',()=>saveDecision(issue,b.dataset.decision)));$('#reopen')?.addEventListener('click',()=>{if(dirty||!report){notice(t('staleBlock'),'error');return;}delete decisions[issue.id];render();notice('');$('[data-decision="reviewed"]')?.focus();});}
function saveDecision(issue,next){if(dirty||!report){notice(t('staleBlock'),'error');return;}const reason=$('#review-reason').value.trim();if(reason.length<3){notice(t('reasonRequired'),'error');$('#review-reason').focus();return;}decisions[issue.id]={status:next,reason,signature:issueSignature(issue),at:new Date().toISOString()};render();notice(t('reasonSaved'),'success');$(`[data-decision="${next}"]`)?.focus();}
function renderCoverage(){const coverage=report?.coverage||[];const checked=coverage.filter(c=>c.status==='checked').length;const partial=coverage.filter(c=>c.status==='partial').length;const skipped=coverage.length-checked-partial;$('#coverage').innerHTML=`<b>${t('coverage')}</b><span>${checked} ${t('rulesChecked')}${partial?' · '+partial+' '+t('checksPartial'):''}${skipped?' · '+skipped+' '+t('checksSkipped'):''} · ${t('unassessed')}${report?' · '+report.engine.version:''}</span>${report?.warnings?.length?`<details class="coverage-warnings"><summary>${report.warnings.length} ${t('warning')}</summary><ul>${report.warnings.map(w=>`<li>${escape(w.message)}</li>`).join('')}</ul></details>`:''}`;}
function downloadable(){if(dirty||!report){notice(t(dirty?'staleBlock':'downloadBefore'),'error');return false;}return true;}
function project(){return {schema:'cliplint-project',schemaVersion:1,exportedAt:new Date().toISOString(),language:lang,syntheticExample:isSample,sourceName,inputs:currentInputs(),reviewInputSnapshot:Object.keys(decisions).length?runSnapshot:null,decisions,report};}
function download(filename,content,type){const blob=new Blob([content],{type});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=filename;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),3000);notice(t('exported'),'success');}
function saveProject(){if(byteLength($('#source').value)>MAX_BYTES){notice(t('sourceLarge'),'error');return;}if(rangeValues.some(r=>r.start.length>30||r.end.length>30)){notice(t('rangeLong'),'error');return;}const p=project();p.rawRanges=rangeValues.map(r=>({...r}));p.report=null;if(dirty)p.decisions={};const content=JSON.stringify(p,null,2);if(byteLength(content)>MAX_PROJECT_BYTES){notice(t('projectLarge'),'error');return;}download('cliplint-project.json',content,'application/json');}
function exportJson(){if(downloadable())download('cliplint-review.json',JSON.stringify(project(),null,2),'application/json');}
function verbatim(text){let longest=2,run=0;for(const char of String(text)){run=char==='`'?run+1:0;if(run>longest)longest=run;}const fence='`'.repeat(longest+1);return fence+'text\n'+text+'\n'+fence;}
function exportMd(){if(!downloadable())return;let md=formatMarkdown(report);md+='\n\n## Human review decisions / 人工判断\n\n';for(const i of report.issues){const d=decisions[i.id];md+=`### ${i.id}: ${i.title}\n- Status: ${d?.status||'open'}\n- Reason:\n\n${verbatim(d?.reason||'Not reviewed')}\n${d?'- Recorded at: '+d.at+'\n':''}\n`;}md+='\n## Original source / 原始稿件\n\n'+verbatim($('#source').value)+'\n\nSemantic fidelity remains unassessed. This is a review record, not certification.\n';download('cliplint-review.md',md,'text/markdown;charset=utf-8');}
function validProject(p){return p&&p.schema==='cliplint-project'&&p.schemaVersion===1&&p.inputs&&typeof p.inputs.source==='string'&&typeof p.inputs.title==='string'&&typeof p.inputs.copy==='string'&&['auto','srt','vtt','json'].includes(p.inputs.format)&&Array.isArray(p.inputs.ranges)&&p.inputs.ranges.length>0&&p.inputs.ranges.length<=MAX_RANGES&&(p.inputs.ranges.every(r=>r&&typeof r.start==='number'&&Number.isFinite(r.start)&&r.start>=0&&typeof r.end==='number'&&Number.isFinite(r.end)&&r.end>r.start)||(Array.isArray(p.rawRanges)&&p.rawRanges.length===p.inputs.ranges.length&&p.rawRanges.every(r=>r&&typeof r.start==='string'&&r.start.length<=30&&typeof r.end==='string'&&r.end.length<=30)))&&byteLength(p.inputs.source)<=MAX_BYTES&&p.inputs.title.length<=500&&p.inputs.copy.length<=10000&&(!('rawRanges' in p)||(Array.isArray(p.rawRanges)&&p.rawRanges.length===p.inputs.ranges.length&&p.rawRanges.every(r=>r&&typeof r.start==='string'&&r.start.length<=30&&typeof r.end==='string'&&r.end.length<=30)));}
async function importProject(file){if(!file)return;try{if(file.size>MAX_PROJECT_BYTES)throw Error(t('projectLarge'));const p=JSON.parse(await file.text());if(!validProject(p))throw Error(t('badProject'));lang=p.language==='en'?'en':'zh';$('#source').value=p.inputs.source;$('#format').value=p.inputs.format;$('#draft-title').value=p.inputs.title;$('#draft-copy').value=p.inputs.copy;rangeValues=p.rawRanges?.map(r=>({start:String(r.start),end:String(r.end)}))||p.inputs.ranges.map(r=>({start:String(r.start),end:String(r.end)}));isSample=p.syntheticExample===true;sourceName=typeof p.sourceName==='string'?p.sourceName.slice(0,200):'imported-transcript';const safeDecisions={};if(p.reviewInputSnapshot===snapshot()&&p.decisions&&typeof p.decisions==='object'){for(const [id,d]of Object.entries(p.decisions).slice(0,5000)){if(d&&['reviewed','dismissed'].includes(d.status)&&typeof d.reason==='string'&&d.reason.trim().length>=3&&d.reason.length<=2000&&typeof d.at==='string'&&Number.isFinite(Date.parse(d.at)))safeDecisions[id]={status:d.status,reason:d.reason,at:d.at,signature:d.signature};}}applyLanguage();runReview(false,safeDecisions);if(report)notice(t('loadedProject'),'success');}catch(e){notice([t('fileLarge'),t('projectLarge')].includes(e.message)?e.message:t('badProject'),'error');}}
function renderAbout(){const rules=Array.isArray(RULES)?RULES:Object.values(RULES||{});$('#about-content').innerHTML=lang==='zh'?`<p>ClipLint 是一个本地优先的发布前检查原型。它用确定性规则与轻量启发式，提示剪辑边界、遗漏上下文和文案中的潜在变化。</p><h3>它实际检查什么</h3><p>时间范围和连接处、附近的限定或否定表达，以及文案中的数字和带引号的引述。提示会附上来源片段，供人工核对。不同规则可能跳过不适用的输入。</p><h3>它不能说明什么</h3><p>它不判断采访内容的真实性、法律风险、完整语义或剪辑是否误导。数字换算、同义改写、反讽、长距离上下文、转写错误和中英文以外的语言可能漏检或误报。没有提示也不代表通过。</p><h3>隐私与保存</h3><p>应用代码不发送稿件、不调用模型 API、不使用遥测，也不自动写入浏览器存储。线上站点会加载自身静态资源，并由托管平台管理访问。审校内容只在本页内存中；导出的项目与报告会包含完整原文。离线运行可完全不联网。</p><h3>版本 0.1.0</h3><p>初始可运行原型，尚未经过真实编辑流程验证。合成示例是虚构的测试材料。未来的语义模型能力未在此版本实现。</p>`:`<p>ClipLint is a local-first pre-publication review prototype. Deterministic rules and lightweight heuristics surface possible changes at edit boundaries, omitted context, and publishing copy.</p><h3>What it checks</h3><p>Range validity and joins, nearby qualifications or negation, and numbers or quoted wording in copy. Signals link to source cues for human review. Rules may skip inputs they do not cover.</p><h3>What it cannot establish</h3><p>It does not assess factual truth, legal risk, full semantics, or whether an edit is misleading. Arithmetic, paraphrase, irony, long-distance context, transcription errors, and languages beyond English and Chinese can cause missed flags or false positives. No flags is not a pass.</p><h3>Privacy and saving</h3><p>The application does not send transcript data, call model APIs, use telemetry, or automatically write browser storage. The hosted site loads its own static assets, and hosting access is managed by the platform. Review data stays in page memory. Downloads include full source text. Running the app locally can be fully offline.</p><h3>Version 0.1.0</h3><p>Working initial prototype, not validated in real editorial workflows. The synthetic example is fictional test material. A semantic-model layer is not implemented.</p>`;if(report){$('#about-content').insertAdjacentHTML('beforeend',`<h3>${t('coverage')}</h3><ul>${report.coverage.map(c=>{const rule=rules.find(r=>r.id===c.ruleId);return `<li><b>${escape(lang==='zh'?zhRules[c.ruleId]?.title||rule?.name||c.ruleId:rule?.name||c.ruleId)}</b> · ${c.status==='checked'?(lang==='zh'?'已运行':'checked'):c.status==='partial'?(lang==='zh'?'部分检查':'partial'):(lang==='zh'?'未运行':'skipped')}${c.reason?`<br>${escape(c.reason)}`:''}</li>`;}).join('')}</ul>${report.warnings.length?`<h3>${t('warning')}</h3><ul>${report.warnings.map(w=>`<li>${escape(w.message)}</li>`).join('')}</ul>`:''}`);}}
$('#source').addEventListener('input',()=>{isSample=false;updateSampleTag();setDirty();});for(const id of ['draft-title','draft-copy','format'])$('#'+id).addEventListener('input',()=>{setDirty();});$('#add-range').addEventListener('click',()=>{if(rangeValues.length>=MAX_RANGES){notice(t('maxRanges'),'error');return;}rangeValues.push({start:'0',end:'4'});renderRanges();setDirty();$('#ranges .range-row:last-child input')?.focus();});$('#run-review').addEventListener('click',()=>runReview());$('#load-sample').addEventListener('click',()=>{loadSample();notice(t('syntheticLoad'));});$('#language').addEventListener('click',()=>{const pristine=isSample&&snapshot()===sampleSnapshot&&Object.keys(decisions).length===0;lang=lang==='zh'?'en':'zh';applyLanguage();if(pristine)loadSample();});$('#upload-source').addEventListener('click',()=>$('#source-file').click());$('#source-file').addEventListener('change',async e=>{const f=e.target.files[0];e.target.value='';if(!f)return;if(f.size>MAX_BYTES){notice(t('fileLarge'),'error');return;}try{$('#source').value=await f.text();$('#format').value=/\.srt$/i.test(f.name)?'srt':/\.vtt$/i.test(f.name)?'vtt':/\.json$/i.test(f.name)?'json':'auto';sourceName=f.name;isSample=false;updateSampleTag();setDirty();notice(t('loadedSource'));}catch{notice(t('invalid')+t('badProject'),'error');}});$('#import-project').addEventListener('click',()=>$('#project-file').click());$('#project-file').addEventListener('change',e=>{const f=e.target.files[0];e.target.value='';importProject(f);});$('#save-project').addEventListener('click',saveProject);$('#export-json').addEventListener('click',exportJson);$('#export-md').addEventListener('click',exportMd);$('#about').addEventListener('click',()=>{renderAbout();$('#about-dialog').showModal();});$('#close-about').addEventListener('click',()=>$('#about-dialog').close());$('#about-dialog').addEventListener('click',e=>{if(e.target===$('#about-dialog')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close();}});
// Translations intentionally preserve the engine's original message in evidence details.
try{const module=await import('./rule-labels.js');zhRules=module.zhRules;}catch{/* English engine text remains a safe fallback. */}
applyLanguage();loadSample();
